changeSet.sql:
CREATE TABLE IF NOT EXISTS public.shipping_methods ( id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, fee numeric NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, CONSTRAINT shipping_methods_pkey PRIMARY KEY (id) );
CREATE TABLE IF NOT EXISTS public.payment_methods ( id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, is_active boolean NOT NULL DEFAULT true, CONSTRAINT payment_methods_pkey PRIMARY KEY (id) );
CREATE TABLE IF NOT EXISTS public.message_templates ( id uuid NOT NULL DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, channel text NOT NULL, subject text, body text NOT NULL, name character varying, description text, variables text, is_active boolean DEFAULT true, updated_at timestamp with time zone DEFAULT now(), CONSTRAINT message_templates_pkey PRIMARY KEY (id) );
CREATE TABLE IF NOT EXISTS public.cms_articles ( id uuid NOT NULL DEFAULT gen_random_uuid(), title character varying NOT NULL, slug character varying NOT NULL UNIQUE, category character varying NOT NULL DEFAULT 'guide', summary text, content text, cover_image text, author_name character varying DEFAULT 'Ban Biên Tập SmartBox', status character varying NOT NULL DEFAULT 'published', view_count integer NOT NULL DEFAULT 0, tags text, published_at timestamp with time zone DEFAULT now(), created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT cms_articles_pkey PRIMARY KEY (id) );
CREATE TABLE IF NOT EXISTS public.cms_banners ( id uuid NOT NULL DEFAULT gen_random_uuid(), title character varying NOT NULL, image_url text NOT NULL, target_url text, position character varying NOT NULL DEFAULT 'hero_home', display_order integer NOT NULL DEFAULT 1, is_active boolean NOT NULL DEFAULT true, click_count integer NOT NULL DEFAULT 0, start_date timestamp with time zone DEFAULT now(), end_date timestamp with time zone DEFAULT (now() + '6 mons'::interval), created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT cms_banners_pkey PRIMARY KEY (id) );
CREATE TABLE IF NOT EXISTS public.cms_reviews ( id uuid NOT NULL DEFAULT gen_random_uuid(), product_id uuid, product_name character varying NOT NULL, customer_name character varying NOT NULL, customer_email character varying, customer_phone character varying, rating integer NOT NULL DEFAULT 5, title character varying, comment text, images text, status character varying NOT NULL DEFAULT 'pending', reject_reason text, admin_reply text, admin_replied_at timestamp with time zone, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT cms_reviews_pkey PRIMARY KEY (id) );
CREATE TABLE IF NOT EXISTS public.cms_faqs ( id uuid NOT NULL DEFAULT gen_random_uuid(), question text NOT NULL, answer text NOT NULL, category character varying NOT NULL DEFAULT 'general', display_order integer NOT NULL DEFAULT 1, is_published boolean NOT NULL DEFAULT true, helpful_count integer NOT NULL DEFAULT 0, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT cms_faqs_pkey PRIMARY KEY (id) );
INSERT INTO public.payment_methods (name, is_active) VALUES ('Cổng VNPAY (QR / ATM / Visa)', true), ('Thanh toán khi nhận hàng (COD)', true), ('Chuyển khoản trực tiếp', true) ON CONFLICT DO NOTHING;
INSERT INTO public.shipping_methods (name, fee, is_active) VALUES ('Giao hàng & Lắp đặt tiêu chuẩn', 30000, true), ('Giao hàng & Lắp đặt hỏa tốc 2H', 50000, true) ON CONFLICT DO NOTHING;
